// === Tab: mySketch ===
/* ======================= SPLASH + OJOS + CÍRCULOS DE FONDO ======================= */

let baseLayer;
let eyes;
let movingCircles = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 255);
  baseLayer = new Splash(createVector(width / 2, height / 2), 180, new Palette().randomSoft());
  eyes = new GooglyEyes(createVector(width / 2, height / 2 + 50), 40);

  // Crear círculos de fondo
  for (let i = 0; i < 12; i++) {
    movingCircles.push(new MovingCircle());
  }
}

function draw() {
  background(255);

  // Fondo animado con círculos que se mueven
  for (let c of movingCircles) {
    c.update();
    c.display();
  }

  // Dibujo principal
  baseLayer.paint();
  eyes.update();
  eyes.draw();
}

/* ======================= CLASE DE CÍRCULOS EN MOVIMIENTO ======================= */
class MovingCircle {
  constructor() {
    this.reset();
  }

  reset() {
    this.x = random(-200, width + 200);
    this.y = random(height);
    this.r = random(80, 200);
    this.speed = random(0.5, 2);
    this.hue = random(0, 360);
  }

  update() {
    this.x += this.speed;
    if (this.x - this.r > width) {
      this.reset();
      this.x = -this.r;
    }
  }

  display() {
    noStroke();
    fill(this.hue, 80, 90, 80);
    ellipse(this.x, this.y, this.r);
  }
}

/* ======================= SPLASH ======================= */

class Splash {
  constructor(c, poolR, pal) {
    this.c = c.copy();
    this.poolR = poolR;
    this.pal = pal;

    this.armCount = Math.floor(random(26, 44));
    this.minLen = random(140, 210);
    this.maxLen = random(280, 440);
    this.branchProb = 0.4;
    this.wobble = random(1, 50);
    this.viscosity = random(0.01, 0.1);
  }

  paint() {
    push();
    noStroke();

    const puddleLayers = 28;
    for (let i = puddleLayers; i >= 1; i--) {
      const rr = this.poolR * map(i, 1, puddleLayers, 0.55, 1.35) * (1 + 0.1 * noise(i * 0.13));
      const col = this.pal.mix(map(i, 1, puddleLayers, 0, 1));
      fill(col);
      ellipse(
        this.c.x + randomGaussian() * 6,
        this.c.y + randomGaussian() * 6,
        rr * 2,
        rr * 2
      );
    }

    for (let a = 0; a < this.armCount; a++) {
      const baseAng = TWO_PI * a / this.armCount + random(-0.08, 0.08);
      const len = random(this.minLen, this.maxLen);
      const steps = Math.max(1, Math.floor(len / 4));
      const sw0 = map(this.viscosity, 0, 1, 9, 16) * random(0.8, 1.25);
      const taperPow = map(this.viscosity, 0, 1, 0.9, 2.3);

      const c0 = this.pal.mix(random(0, 0.6));
      const c1 = this.pal.mix(random(0.4, 1));

      const start = p5.Vector.fromAngle(baseAng)
        .mult(this.poolR * 0.9 + random(4, 10))
        .add(this.c);

      let p = start.copy();
      let dir = p5.Vector.fromAngle(baseAng);
      const nOff = random(1000);

      for (let s = 0; s < steps; s++) {
        const t = s / steps;
        const ang = baseAng + this.wobble * (noise(nOff + s * 0.03) - 0.5);
        dir = p5.Vector.fromAngle(ang);
        const stepLen = 10 + 3 * pow(1 - t, 2);
        const q = p5.Vector.add(p, p5.Vector.mult(dir, stepLen));

        const cc = lerpColor(c0, c1, easeOutCubic(t));
        const sw = Math.max(1, sw0 * pow(1 - t, taperPow)) * random(1.5, 2);

        stroke(cc);
        strokeWeight(sw);
        line(p.x, p.y, q.x, q.y);

        if (random(1) < this.branchProb * (1 - t)) {
          const bAng = ang + random(-1.2, 1.2);
          const bLen = stepLen * random(12, 24);
          this.drawBranch(q.copy(), bAng, bLen, sw * 0.5, c0, c1);
        }
        p = q;
      }
    }
    pop();
  }

  drawBranch(start, ang, len, sw, c0, c1) {
    var steps = Math.max(1, Math.floor(len / 3));
    var nOff = random(1000);
    var p = start.copy();
    for (let s = 0; s < steps; s++) {
      var t = s / steps;
      const a = ang + 0.5 * (noise(nOff + s * 0.07) - 0.5);
      var dir = p5.Vector.fromAngle(a);
      var stepLen = 3;
      var q = p5.Vector.add(p, p5.Vector.mult(dir, stepLen));
      var cc = lerpColor(c0, c1, t);
      stroke(cc);
      strokeWeight(sw * pow(1 - t, 1.6));
      line(p.x, p.y, q.x, q.y);
      p = q;
    }
  }
}

/* ======================= OJOS ======================= */

class GooglyEyes {
  constructor(anchor, baseR) {
    this.anchor = anchor.copy();
    this.eyeR = constrain(baseR, 20, 25);
    const gap = this.eyeR * random(1.5, 1.6);
    const base = this.anchor.copy().add(0, -this.eyeR * 0.25);
    const leftCenter = base.copy().add(-gap * 0.6, 0);
    const rightCenter = base.copy().add(gap * 0.6, 0);
    this.left = new Eye(leftCenter, this.eyeR);
    this.right = new Eye(rightCenter, this.eyeR);
  }

  update() {
    this.left.update();
    this.right.update();
  }

  draw() {
    this.left.draw();
    this.right.draw();
    noFill();
    stroke(0, 0, 40, 150);
    strokeWeight(5);
    const wSmile = this.eyeR * 2.5;
    arc(this.anchor.x, this.anchor.y + this.eyeR * 0.95, wSmile, wSmile * 0.7, 0.15, PI - 0.15);
  }
}

class Eye {
  constructor(c, r) {
    this.c = c.copy();
    this.r = r;
    this.pupilR = r * 0.4;
    this.nOffX = random(1000);
    this.nOffY = random(2000);
    this.pupilCx = this.c.x;
    this.pupilCy = this.c.y;
  }

  update() {
    const range = this.r * 0.4;
    let tx = map(noise(this.nOffX + frameCount * 0.01), 0, 1, -range, range);
    let ty = map(noise(this.nOffY + frameCount * 0.014), 0, 1, -range, range);

    if (dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), this.c.x, this.c.y) < this.r * 10) {
      const toM = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - this.c.x, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - this.c.y);
      toM.limit(range * 2);
      tx = lerp(tx, toM.x, 0.5);
      ty = lerp(ty, toM.y, 0.5);
    }

    this.pupilCx = lerp(this.pupilCx, this.c.x + tx, 0.15);
    this.pupilCy = lerp(this.pupilCy, this.c.y + ty, 0.15);
  }

  draw() {
    noStroke();
    fill(255);
    ellipse(this.c.x, this.c.y, this.r * 2, this.r * 2);
    fill(25);
    ellipse(this.pupilCx, this.pupilCy, this.pupilR * 2, this.pupilR * 2);
    fill(255, 230);
    ellipse(this.pupilCx - this.pupilR * 0.35, this.pupilCy - this.pupilR * 0.35, this.pupilR * 0.6, this.pupilR * 0.6);
  }
}

/* ======================= UTILIDADES ======================= */

class Palette {
  randomSoft() {
    var base = random(0, 360);
    this.h1 = base;
    this.h2 = base + random(110, 160);
    this.h3 = base + random(200, 260);
    return this;
  }

  mix(t) {
    colorMode(HSB, 360, 100, 100, 255);
    const h = lerp(this.h1, this.h2, t);
    const s = 70;
    const b = 90;
    const c = color(h % 360, s, b);
    colorMode(RGB, 255);
    return c;
  }
}

function easeOutCubic(t) {
  const tt = constrain(t, 0, 1);
  return 1 - pow(1 - tt, 3);
}

